def transform(grid):
    h = len(grid)
    w = len(grid[0])

    # Extract distinct colors in order of first appearance
    colors = []
    for row in grid:
        for c in row:
            if c != 0 and c not in colors:
                colors.append(c)

    if not colors:
        return grid

